/**
 * GameState — 唯一状态源 (Single Source of Truth)
 *
 * 所有游戏数据集中在此对象中。每个模块通过 getState()/updateState() 读写。
 * 使用 Proxy 实现变更追踪（dirty flag），驱动按需渲染。
 */

// ====== 默认初始状态 ======
function createDefaultState() {
  const now = Date.now();
  return {
    // --- 元数据 ---
    version: '1.0.0',
    createdAt: now,
    lastPlayedAt: now,
    playTime: 0,

    // --- 玩家身份 ---
    player: {
      name: '无名',
      gender: 'male',
      age: 20,
      birthday: { month: 6, day: 15 },

      // 街头 4 维属性 (0-100)
      physique: 22,       // 体质
      intelligence: 20,   // 智力
      agility: 24,        // 敏捷
      mental: 26,         // 心智

      // 职场 7 维属性 (进入职场后初始化)
      corporate: {
        hair: 100,
        dignity: 60,
        upwardMgmt: 20,
        kpi: 20,
        ability: 30,
        risk: 0,
        popularity: 30,
      },

      // 阶段与时间
      phase: 'street',       // 'street' | 'corporate'
      day: 1,
      corpYear: 0,           // 入职年数
      corpQuarter: 1,        // 1-4
      timeSlot: 'morning',   // 'morning' | 'afternoon' | 'evening'
    },

    // --- 经济 ---
    resources: {
      cash: 2000,            // 现金（元）
      bankBalance: 0,        // 银行存款
      debt: 5500,            // 当前欠款
      loanPrincipal: 5500,   // 原始借款额
      loanDay: 0,            // 借款日
      dailyInterest: 0.003,  // 日息 0.3%
      totalEarned: 0,        // 终身总收入
    },

    // --- 基本需求 (0-100) ---
    needs: {
      hunger: 70,
      fatigue: 15,
      hygiene: 75,
      happiness: 55,
    },

    // --- 派生状态 ---
    status: {
      health: 100,
      fame: 0,
      emotionalState: 'stable', // stable|happy|sad|angry|stressed|depressed
      sick: false,
      injured: false,
    },

    // --- 技能 (level: 0-100, xp: 0-1000) ---
    skills: {
      cooking:    { level: 0, xp: 0 },
      repair:     { level: 0, xp: 0 },
      coding:     { level: 0, xp: 0 },
      english:    { level: 0, xp: 0 },
      driving:    { level: 0, xp: 0 },
      sales:      { level: 0, xp: 0 },
      management: { level: 0, xp: 0 },
      accounting: { level: 0, xp: 0 },
      electrician:{ level: 0, xp: 0 },
      welding:    { level: 0, xp: 0 },
    },
    certificates: [],
    education: 0,

    // --- 物品栏 ---
    inventory: {
      items: [],             // [{ id, qty, avgBuyPrice }]
      capacity: 20,          // 基础容量
      equipment: {
        head: null, body: null, feet: null, hand: null, accessory: null,
      },
    },

    // --- 住所 ---
    housing: {
      tier: 0,               // 0=露宿, 1=合租床位, 2=单间, 3=一居室
      rentedDay: 0,          // 租房日
      storageRented: false,  // 是否租了仓库
      storageCapacity: 0,    // 仓库额外容量
    },

    // --- 人际关系 ---
    relationships: {},       // { npcId: { affinity: -100~100, met: bool } }

    // --- 交易系统 ---
    trade: {
      currentLocation: 'slum',
      goodsPrices: {},       // { locationKey: { goodId: price } }
      priceTrends: {},
      lastPriceUpdate: 0,
    },

    // --- 就业 ---
    employment: {
      currentJob: null,
      jobStartDay: 0,
      completedShifts: {},
    },

    // --- 职场 ---
    corporate: {
      company: null,
      rank: 'P5',
      department: 'engineering',
      joinedDay: 0,
      perfHistory: [],       // [{ year, quarter, grade, score }]
      consecutiveC: 0,
      quarterlyActions: 3,
      actionsUsed: 0,
      team: [],
      stocks: [],
      stockMarket: {},
      projects: [],
      completedProjects: [],
    },

    // --- 标志位 ---
    flags: {
      tutorialCompleted: false,
      gameOver: false,
      victory: false,
      victoryType: null,
      gameOverReason: null,
      ageThisYear: false,
      seenNewsToday: [],
    },

    // --- 事件与消息 ---
    activeNews: [],
    newsHistory: [],
    messageLog: [],          // [{ day, text, type }]
  };
}

// ====== 状态管理器 ======
class GameStateManager {
  constructor() {
    this._state = null;
    this._dirtyFlags = new Set();
    this._listeners = [];
  }

  /** 初始化新游戏 */
  newGame() {
    this._state = createDefaultState();
    this._markAllDirty();
    this._notify();
    return this._state;
  }

  /** 获取当前完整状态（只读引用，请勿直接修改嵌套对象） */
  getState() {
    if (!this._state) {
      throw new Error('GameState not initialized. Call newGame() or loadGame() first.');
    }
    return this._state;
  }

  /** 获取状态某个路径的值 */
  get(path) {
    const parts = path.split('.');
    let val = this.getState();
    for (const p of parts) {
      if (val == null) return undefined;
      val = val[p];
    }
    return val;
  }

  /**
   * 更新状态某个路径的值
   * 用法: update('player.age', 25) 或 update('player', { age: 25, ... })
   */
  update(path, value) {
    const parts = path.split('.');
    const state = this.getState();

    // 导航到父对象
    let parent = state;
    for (let i = 0; i < parts.length - 1; i++) {
      parent = parent[parts[i]];
    }

    const key = parts[parts.length - 1];
    parent[key] = value;

    // 标记脏路径
    this._dirtyFlags.add(path);
    this._notify();
  }

  /** 批量更新（用于一次性修改多个字段） */
  batchUpdate(updates) {
    for (const [path, value] of Object.entries(updates)) {
      const parts = path.split('.');
      const state = this.getState();
      let parent = state;
      for (let i = 0; i < parts.length - 1; i++) {
        parent = parent[parts[i]];
      }
      parent[parts[parts.length - 1]] = value;
      this._dirtyFlags.add(path);
    }
    this._notify();
  }

  /** 添加消息到日志 */
  addMessage(text, type = 'info') {
    const state = this.getState();
    state.messageLog.push({
      day: state.player.day,
      text,
      type, // 'info'|'success'|'danger'|'event'|'warning'
    });
    // 限制日志长度
    if (state.messageLog.length > 500) {
      state.messageLog = state.messageLog.slice(-300);
    }
    this._dirtyFlags.add('messageLog');
    this._notify();
  }

  /** 导入存档 */
  importState(savedState) {
    this._state = savedState;
    this._state.lastPlayedAt = Date.now();
    this._markAllDirty();
    this._notify();
  }

  /** 检查路径是否脏（自上次 cleanDirty 后） */
  isDirty(path) {
    return this._dirtyFlags.has(path);
  }

  /** 清除所有脏标记（渲染后调用） */
  cleanAllDirty() {
    this._dirtyFlags.clear();
  }

  /** 订阅状态变更 */
  onChange(callback) {
    this._listeners.push(callback);
  }

  // ====== 内部方法 ======
  _markAllDirty() {
    this._dirtyFlags.add('*');
  }

  _notify() {
    for (const cb of this._listeners) {
      try { cb(this._state); } catch (e) { /* 静默 */ }
    }
  }
}

// ====== 单例导出 ======
const StateManager = new GameStateManager();

// 使其在全局可访问（方便调试）
if (typeof window !== 'undefined') {
  window.StateManager = StateManager;
}

/**
 * 地图地点数据
 * 11个地点，每个有：名称、描述、类型、可用工作、旅行连接
 */

const LOCATIONS = {
  slum: {
    id: 'slum',
    name: '城中村',
    desc: '鱼龙混杂的城中村，房租便宜，机会也多。',
    type: 'residential',
    jobs: ['waste_recycling', 'street_vending_goods'],
    priceMod: { water: 0.9, snacks: 0.85, noodles: 0.8, scrap_metal: 1.6, scrap_paper: 1.5, scrap_plastic: 1.5, daily_use: 0.7 },
  },
  wholesaleMarket: {
    id: 'wholesaleMarket',
    name: '批发市场',
    desc: '各种商品批发的集散地，进货的天堂。',
    type: 'commercial',
    jobs: ['street_vending_goods', 'warehouse_worker'],
    priceMod: { water: 0.6, snacks: 0.55, noodles: 0.5, cigarettes: 0.7, beer: 0.7, clothing: 0.6, electronics: 0.55, fruits: 0.5, vegetables: 0.5 },
  },
  construction: {
    id: 'construction',
    name: '建筑工地',
    desc: '尘土飞扬的建筑工地，到处是钢筋水泥。',
    type: 'industrial',
    jobs: ['manual_labor_construction', 'skilled_labor_construction'],
    priceMod: {},
  },
  factoryZone: {
    id: 'factoryZone',
    name: '工业区',
    desc: '工厂聚集的工业区，机器轰鸣声不绝于耳。',
    type: 'industrial',
    jobs: ['factory_work_assembly', 'factory_overtime', 'security_guard', 'warehouse_worker'],
    priceMod: { water: 1.1, snacks: 1.0, noodles: 1.0, cigarettes: 1.2, beer: 1.2 },
  },
  school: {
    id: 'school',
    name: '大学城',
    desc: '高校云集的大学城，年轻人多，机会特殊。',
    type: 'institutional',
    jobs: ['school_maintenance', 'package_delivery', 'tutoring'],
    priceMod: { water: 0.8, snacks: 0.9, noodles: 0.9, fruits: 1.0, vegetables: 1.0 },
  },
  commercialDist: {
    id: 'commercialDist',
    name: '商业区',
    desc: '繁华的商业地段，人来人往，商机无限。',
    type: 'commercial',
    jobs: ['street_vending_food', 'food_stall', 'barber', 'cleaning_service', 'repair_service', 'delivery_rider', 'street_performer'],
    priceMod: { water: 1.3, snacks: 1.4, noodles: 1.3, cigarettes: 1.4, beer: 1.5, clothing: 1.5, electronics: 1.6, fruits: 1.6, vegetables: 1.5 },
  },
  techPark: {
    id: 'techPark',
    name: '科技园',
    desc: '互联网大厂的聚集地，高楼林立，精英云集。',
    type: 'corporate',
    jobs: [],
    priceMod: {},
  },
  hospital: {
    id: 'hospital',
    name: '医院',
    desc: '看病治疗的地方。健康是革命的本钱。',
    type: 'service',
    jobs: [],
    priceMod: {},
  },
  bank: {
    id: 'bank',
    name: '银行',
    desc: '存取款、办理贷款。',
    type: 'service',
    jobs: [],
    priceMod: {},
  },
  park: {
    id: 'park',
    name: '公园',
    desc: '城市中的绿洲，可以放松身心。',
    type: 'recreation',
    jobs: [],
    priceMod: {},
  },
  trainingCenter: {
    id: 'trainingCenter',
    name: '培训中心',
    desc: '学习技能、考取证书的地方。投资自己。',
    type: 'education',
    jobs: [],
    priceMod: {},
  },
};

// 旅行图（哪些地点之间可以直接通行）
const TRAVEL_GRAPH = {
  slum:            ['wholesaleMarket', 'construction', 'park', 'bank'],
  wholesaleMarket: ['slum', 'commercialDist', 'factoryZone'],
  construction:    ['slum', 'commercialDist'],
  factoryZone:     ['wholesaleMarket', 'school', 'hospital'],
  school:          ['factoryZone', 'park', 'trainingCenter'],
  commercialDist:  ['wholesaleMarket', 'construction', 'techPark', 'hospital'],
  techPark:        ['commercialDist'],
  hospital:        ['factoryZone', 'commercialDist'],
  bank:            ['slum', 'commercialDist'],
  park:            ['slum', 'school', 'commercialDist'],
  trainingCenter:  ['school'],
};

/** 获取地点信息 */
function getLocation(locKey) {
  return LOCATIONS[locKey] || null;
}

/** 获取从当前地点可到达的地点 */
function getReachableLocations(currentKey) {
  return TRAVEL_GRAPH[currentKey] || [];
}

/** 获取当前地点可做的工作列表 */
function getJobsAtLocation(locKey) {
  const loc = LOCATIONS[locKey];
  if (!loc) return [];
  return loc.jobs || [];
}

