41	/** 检查工作需求是否满足 */
42	function checkJobRequirements(job, state) {
43	  const reqs = job.requirements || {};
44	  const p = state.player;
45	  const s = state.skills;
46	
47	  if (reqs.minAge && p.age < reqs.minAge) return `需要年满${reqs.minAge}岁`;
48	  if (reqs.maxAge && p.age > reqs.maxAge) return `年龄超过${reqs.maxAge}岁限制`;
49	  if (reqs.physique && p.physique < reqs.physique) return `体质不足 (需要${reqs.physique})`;
50	  if (reqs.intelligence && p.intelligence < reqs.intelligence) return `智力不足 (需要${reqs.intelligence})`;
51	  if (reqs.agility && p.agility < reqs.agility) return `敏捷不足 (需要${reqs.agility})`;
52	  if (reqs.mental && p.mental < reqs.mental) return `心智不足 (需要${reqs.mental})`;
53	  if (reqs.cooking && s.cooking.level < reqs.cooking) return `烹饪技能不足 (需要${reqs.cooking})`;
54	  if (reqs.repair && s.repair.level < reqs.repair) return `维修技能不足 (需要${reqs.repair})`;
55	  if (reqs.sales && s.sales.level < reqs.sales) return `销售技能不足 (需要${reqs.sales})`;
56	  if (reqs.english && s.english.level < reqs.english) return `英语技能不足 (需要${reqs.english})`;
57	
58	  return null; // 通过
59	}
