61	/** 估算工作收入 */
62	function estimateJobPay(job, state) {
63	  // 模拟3次取平均
64	  let total = 0;
65	  for (let i = 0; i < 10; i++) {
66	    total += job.payCalc(state);
67	  }
68	  return Math.floor(total / 10);
69	}
