158	/** 初始化各地商品价格 */
159	function initializePrices() {
160	  const state = StateManager.getState();
161	  for (const locKey of Object.keys(LOCATIONS)) {
162	    state.trade.goodsPrices[locKey] = {};
163	    const loc = LOCATIONS[locKey];
164	    for (const good of GOODS) {
165	      let price = good.basePrice;
166	      if (loc.priceMod && loc.priceMod[good.id]) {
167	        price *= loc.priceMod[good.id];
168	      }
169	      // 随机波动 ±10%
170	      price *= 0.9 + Math.random() * 0.2;
171	      price = Math.round(price * 100) / 100;
172	      state.trade.goodsPrices[locKey][good.id] = price;
173	    }
174	  }
175	  state.trade.lastPriceUpdate = state.player.day;
176	}
