673	function doStreetJob(job) {
674	  const state = StateManager.getState();
675	
676	  // 扣除启动资金
677	  if (job.startupCost) {
678	    state.resources.cash -= job.startupCost;
679	  }
680	
681	  // 计算收入
682	  const pay = job.payCalc(state);
683	  state.resources.cash += pay;
684	  state.resources.totalEarned += pay;
685	  state.employment.completedShifts[job.id] = (state.employment.completedShifts[job.id] || 0) + 1;
686	
687	  // 应用效果
688	  if (job.effects) {
689	    if (job.effects.fatigue) state.needs.fatigue = Math.min(100, state.needs.fatigue + job.effects.fatigue);
690	    if (job.effects.hygiene) state.needs.hygiene = Math.max(0, Math.min(100, state.needs.hygiene + job.effects.hygiene));
691	    if (job.effects.happiness) state.needs.happiness = Math.max(0, Math.min(100, state.needs.happiness + job.effects.happiness));
692	    if (job.effects.mental) state.player.mental = Math.max(0, Math.min(100, state.player.mental + job.effects.mental));
693	    if (job.effects.fame) state.status.fame = Math.max(0, Math.min(100, state.status.fame + job.effects.fame));
694	
695	    // 技能经验
696	    addSkillXp('cooking', job.effects.cookingXp || 0);
697	    addSkillXp('repair', job.effects.repairXp || 0);
698	    addSkillXp('agility', job.effects.agilityXp || 0);
699	    addSkillXp('sales', job.effects.salesXp || 0);
700	    addSkillXp('physique', job.effects.physiqueXp || 0);
701	    addSkillXp('intelligence', job.effects.intelligenceXp || 0);
702	    addSkillXp('english', job.effects.englishXp || 0);
703	  }
704	
705	  // 属性经验转化
706	  if (job.effects) {
707	    if (job.effects.agilityXp) state.player.agility = Math.min(100, state.player.agility + job.effects.agilityXp * 0.1);
708	    if (job.effects.physiqueXp) state.player.physique = Math.min(100, state.player.physique + job.effects.physiqueXp * 0.1);
709	    if (job.effects.intelligenceXp) state.player.intelligence = Math.min(100, state.player.intelligence + job.effects.intelligenceXp * 0.1);
710	  }
