712	  // 受伤/生病风险（情绪影响风险倍率）
713	  if (job.risk) {
714	    const riskMod = typeof getEmotionWorkModifier === 'function' ? (getEmotionWorkModifier(state).injury || 1) : 1;
715	    if (job.risk.injury && Math.random() < Math.min(1, job.risk.injury * riskMod)) {
716	      state.status.injured = true;
717	      state.status.health = Math.max(0, state.status.health - 15);
718	      StateManager.addMessage('🤕 工作中受伤了！健康-15。建议去医院看看。', 'danger');
719	    }
720	    if (job.risk.illness && Math.random() < Math.min(1, (job.risk.illness || 0) * riskMod)) {
721	      state.status.sick = true;
722	      state.status.health = Math.max(0, state.status.health - 10);
723	      StateManager.addMessage('🤒 你生病了！健康-10。注意休息或去医院。', 'danger');
724	    }
725	  }
726	
727	  StateManager.addMessage(`💰 ${job.name}完成，赚了 ¥${pay}。`, 'success');
