772	function endDay() {
773	  const state = StateManager.getState();
774	
775	  state.player.day++;
776	
777	  // 使用需求系统模块
778	  if (typeof applyNeedsDecay === 'function') applyNeedsDecay(state);
779	  else {
780	    state.needs.hunger = Math.max(0, state.needs.hunger - 18);
781	    state.needs.hygiene = Math.max(0, state.needs.hygiene - 8);
782	  }
783	  // 睡眠恢复（基础25 + 住所加成）
784	  const HOUSING_TIERS = [
785	    { tier: 0, fatigueRecovery: 15, rent: 0, hygieneBonus: 0, happinessBonus: 0 },
786	    { tier: 1, fatigueRecovery: 25, rent: 12, hygieneBonus: 5, happinessBonus: 0 },
787	    { tier: 2, fatigueRecovery: 35, rent: 25, hygieneBonus: 10, happinessBonus: 5 },
788	    { tier: 3, fatigueRecovery: 50, rent: 50, hygieneBonus: 15, happinessBonus: 10 },
789	  ];
790	  const house = HOUSING_TIERS[state.housing?.tier || 0] || HOUSING_TIERS[0];
791	  state.needs.fatigue = Math.max(0, state.needs.fatigue - house.fatigueRecovery);
792	  state.needs.hygiene = Math.min(100, state.needs.hygiene + (house.hygieneBonus || 0));
793	  state.needs.happiness = Math.max(0, Math.min(100, state.needs.happiness - 3 + (house.happinessBonus || 0)));
794	
795	  // 扣房租
796	  if (house.rent > 0) {
797	    if (state.resources.cash >= house.rent) {
798	      state.resources.cash -= house.rent;
799	    } else {
800	      StateManager.addMessage(`⚠️ 付不起房租 ¥${house.rent}！被赶回流落街头。`, 'danger');
801	      state.housing.tier = 0;
802	      state.inventory.capacity = 20 + (state.housing?.storageCapacity || 0);
803	    }
804	  }
805	  // 扣仓库租金
806	  if (state.housing?.storageRented && state.housing?.storageCapacity > 0) {
807	    const storageRent = state.housing.storageCapacity >= 500 ? 50 : 20;
808	    if (state.resources.cash >= storageRent) {
809	      state.resources.cash -= storageRent;
810	    } else {
811	      StateManager.addMessage('⚠️ 付不起仓库租金，仓库被收回。', 'danger');
812	      state.housing.storageRented = false;
813	      state.housing.storageCapacity = 0;
814	      const baseCap = [20, 50, 100, 200][state.housing.tier || 0];
815	      state.inventory.capacity = baseCap;
816	    }
817	  }
818	
819	  // 伤病结算
820	  if (typeof tickHealthStatus === 'function') tickHealthStatus(state);
821	  else {
822	    if (!state.status.sick && !state.status.injured) state.status.health = Math.min(100, state.status.health + 1);
823	    if (state.status.sick) { state.status.health = Math.max(0, state.status.health - 3); if (Math.random() < 0.1) state.status.sick = false; }
824	    if (state.status.injured) { state.status.health = Math.max(0, state.status.health - 2); if (Math.random() < 0.05) state.status.injured = false; }
825	  }
826	
827	  // 需求阈值检查
828	  if (typeof checkNeedsThresholds === 'function') checkNeedsThresholds(state);
829	
830	  // 情绪判定
831	  if (typeof determineEmotionalState === 'function') determineEmotionalState(state);
832	
833	  // 贷款利息
834	  if (state.resources.debt > 0) {
835	    const interest = Math.floor(state.resources.debt * state.resources.dailyInterest);
836	    if (interest > 0) {
837	      state.resources.debt += interest;
838	      StateManager.addMessage(`🏦 欠款利息：+¥${interest}（欠款 ¥${state.resources.debt.toLocaleString()}）`, 'warning');
839	    }
840	  }
841	
842	  // 银行存款利息
843	  if (state.resources.bankBalance > 0) {
844	    const bankInterest = Math.floor(state.resources.bankBalance * 0.001);
845	    if (bankInterest > 0) state.resources.bankBalance += bankInterest;
846	  }
847	
848	  // 每3天更新价格
849	  if (state.player.day - state.trade.lastPriceUpdate >= 3) {
850	    if (typeof updateAllPrices === 'function') updateAllPrices(state);
851	  }
852	
853	  // 新闻事件
854	  if (typeof rollDailyNews === 'function') rollDailyNews(state);
855	  else if (Math.random() < 0.1) triggerRandomEvent(state);
856	
857	  // 清理过期效果
858	  if (typeof dailyCleanup === 'function') dailyCleanup(state);
859	
860	  // 每年年龄增长
861	  if (state.player.day % 365 === 0) {
862	    state.player.age++;
863	    StateManager.addMessage(`🎂 又过了一年，你现在${state.player.age}岁了。`, 'event');
