285	function createActionCard(action, state) {
286	  const card = document.createElement('div');
287	  card.className = 'action-card';
288	  if (action.disabled) {
289	    card.classList.add('disabled');
290	  }
291	
292	  card.innerHTML = `
293	    <div class="card-icon">${action.icon}</div>
294	    <div class="card-title">${action.name}</div>
295	    <div class="card-desc">${action.desc}</div>
296	    <div class="card-meta">
297	      ${action.payEstimate ? `<span class="pay-estimate">💰 ¥${action.payEstimate}</span>` : ''}
