299	      ${action.reqFail ? `<span class="req-fail">⚠ ${action.reqFail}</span>` : ''}
300	    </div>
301	  `;
302	
303	  if (!action.disabled) {
304	    card.addEventListener('click', () => {
305	      if (action.handler) {
306	        action.handler();
307	        renderAll();
308	      }
309	    });
310	  }
311	
312	  return card;
313	}
314	
315	// ====== Trade Tab ======
316	function renderTradeTab(state, parent) {
317	  const locKey = state.trade.currentLocation;
318	  const loc = getLocation(locKey);
319	  const prices = state.trade.goodsPrices[locKey] || {};
320	  const isWholesale = locKey === 'wholesaleMarket';
321	  const goodsList = typeof GOODS !== 'undefined' ? GOODS : [];
322	
323	  // 标题区
324	  const headerDiv = document.createElement('div');
325	  headerDiv.style.cssText = 'display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;';
326	  headerDiv.innerHTML = `
327	    <h3 style="color:var(--text-muted);margin:0;">
328	      📦 ${loc ? loc.name : '当前地点'} — ${isWholesale ? '批发市场（进货价低）' : '零售市场'}
329	    </h3>
330	    <span style="font-size:11px;color:var(--text-muted);">现金: <strong style="color:var(--success)">¥${state.resources.cash.toLocaleString()}</strong></span>
331	  `;
332	  parent.appendChild(headerDiv);
333	
334	  if (goodsList.length === 0) {
335	    parent.innerHTML += '<p style="color:var(--text-muted)">商品数据加载中...</p>';
336	    return;
337	  }
338	
339	  // 背包中的商品（方便快速卖出）
340	  const ownedGoods = state.inventory.items || [];
341	  if (ownedGoods.length > 0) {
342	    const ownedDiv = document.createElement('div');
343	    ownedDiv.style.marginBottom = '16px';
344	    ownedDiv.innerHTML = '<h4 style="color:var(--text-muted);margin-bottom:8px;">🎒 背包中的商品（可卖出）</h4>';
345	    const ownedGrid = document.createElement('div');
346	    ownedGrid.className = 'action-cards';
347	    ownedGrid.style.gridTemplateColumns = 'repeat(auto-fill, minmax(180px, 1fr))';
348	
349	    for (const item of ownedGoods) {
350	      const good = getGoodById(item.id);
351	      if (!good) continue;
352	      const price = prices[good.id] || good.basePrice;
353	      const profitInfo = item.avgBuyPrice
354	        ? (price > item.avgBuyPrice
355	            ? `<span style="color:var(--success)">📈 +¥${((price - item.avgBuyPrice) * item.qty).toFixed(1)}</span>`
356	            : `<span style="color:var(--danger)">📉 -¥${((item.avgBuyPrice - price) * item.qty).toFixed(1)}</span>`)
357	        : '';
358	
359	      const card = document.createElement('div');
360	      card.className = 'action-card';
361	      card.innerHTML = `
362	        <div style="display:flex;justify-content:space-between;align-items:center;">
363	          <div class="card-title" style="margin:0;">${good.name}</div>
364	          <span class="slot-tag">×${item.qty}</span>
365	        </div>
366	        <div class="card-desc" style="margin:4px 0;">
367	          买入均价: ¥${(item.avgBuyPrice || '?')} | 当前价: ¥${price.toFixed(1)}
368	        </div>
369	        <div style="display:flex;justify-content:space-between;align-items:center;">
370	          <span style="font-size:11px;">${profitInfo}</span>
371	          <div style="display:flex;gap:4px;">
372	            <button class="btn btn-sm btn-danger sell-one-btn" data-good="${good.id}">卖1</button>
373	            <button class="btn btn-sm btn-danger sell-all-btn" data-good="${good.id}">全卖</button>
374	          </div>
375	        </div>
376	      `;
377	      ownedGrid.appendChild(card);
378	    }
379	    ownedDiv.appendChild(ownedGrid);
380	    parent.appendChild(ownedDiv);
381	  }
382	
383	  // 市场价格表
384	  const marketLabel = document.createElement('h4');
385	  marketLabel.style.cssText = 'color:var(--text-muted);margin-bottom:8px;';
386	  marketLabel.textContent = isWholesale ? '📋 批发商品（最低5件起批，批发价 = 零售价×0.7）' : '📋 市场商品';
387	  parent.appendChild(marketLabel);
388	
389	  const grid = document.createElement('div');
390	  grid.className = 'action-cards';
391	  grid.style.gridTemplateColumns = 'repeat(auto-fill, minmax(200px, 1fr))';
392	
393	  for (const good of goodsList) {
394	    const price = prices[good.id] || good.basePrice;
395	    const wholesalePrice = isWholesale ? Math.round(price * 0.7 * 100) / 100 : null;
396	
397	    // 价格对比：最低价和最高价
398	    const lowest = getLowestPrice(good.id);
399	    const highest = getHighestPrice(good.id);
400	    const isLowest = lowest.location === locKey;
401	    const isHighest = highest.location === locKey;
402	
403	    const card = document.createElement('div');
404	    card.className = 'action-card';
405	    card.innerHTML = `
406	      <div style="display:flex;justify-content:space-between;align-items:center;">
407	        <div class="card-title" style="margin:0;">${good.name}</div>
408	        <span class="slot-tag">${good.category}</span>
409	      </div>
410	      <div class="card-desc" style="margin:4px 0;">
411	        基准: ¥${good.basePrice}/${good.unit}
412	        ${wholesalePrice ? `<br>批发价: <strong style="color:var(--success)">¥${wholesalePrice.toFixed(1)}</strong>/件 (零售 ¥${price.toFixed(1)})` : ''}
413	      </div>
414	      <div style="font-size:10px;color:var(--text-muted);margin-bottom:6px;">
415	        当前零售价: <strong style="color:${isLowest ? 'var(--success)' : isHighest ? 'var(--danger)' : 'var(--text-primary)'}">¥${price.toFixed(1)}</strong>
416	        ${isLowest ? ' 🟢 全城最低' : ''}${isHighest ? ' 🔴 全城最高' : ''}
417	      </div>
418	      <div style="display:flex;gap:4px;flex-wrap:wrap;">
419	        <button class="btn btn-sm btn-success buy-btn" data-good="${good.id}" data-qty="1">买1</button>
420	        <button class="btn btn-sm btn-success buy-btn" data-good="${good.id}" data-qty="5">买5</button>
421	        ${isWholesale ? `<button class="btn btn-sm btn-primary wholesale-btn" data-good="${good.id}" data-qty="10">批发×10</button>` : ''}
422	      </div>
423	    `;
424	    grid.appendChild(card);
425	  }
426	  parent.appendChild(grid);
427	
428	  // 价格对比速查表
429	  const compareDiv = document.createElement('div');
430	  compareDiv.style.marginTop = '20px';
431	  compareDiv.innerHTML = '<h4 style="color:var(--text-muted);margin-bottom:8px;">📍 各地价格对比</h4>';
432	
433	  const compareTable = document.createElement('div');
434	  compareTable.style.cssText = 'overflow-x:auto;font-size:11px;';
435	  let tableHtml = '<table style="width:100%;border-collapse:collapse;"><thead><tr><th style="padding:4px 8px;text-align:left;border-bottom:1px solid var(--border);color:var(--text-muted);">商品</th>';
436	  for (const lk of Object.keys(LOCATIONS)) {
437	    const l = LOCATIONS[lk];
438	    tableHtml += `<th style="padding:4px 6px;text-align:right;border-bottom:1px solid var(--border);color:var(--text-muted);font-size:10px;">${l.name.substring(0,2)}</th>`;
439	  }
440	  tableHtml += '</tr></thead><tbody>';
441	
442	  for (const good of goodsList) {
443	    tableHtml += `<tr><td style="padding:3px 8px;border-bottom:1px solid rgba(255,255,255,0.03);">${good.name}</td>`;
444	    for (const lk of Object.keys(LOCATIONS)) {
445	      const p = (state.trade.goodsPrices[lk] || {})[good.id] || good.basePrice;
446	      const isLow = getLowestPrice(good.id).location === lk;
447	      const isHigh = getHighestPrice(good.id).location === lk;
448	      const cellStyle = isLow ? 'color:var(--success);font-weight:bold;' : isHigh ? 'color:var(--danger);' : 'color:var(--text-secondary);';
449	      tableHtml += `<td style="padding:3px 6px;text-align:right;border-bottom:1px solid rgba(255,255,255,0.03);${cellStyle}">${p.toFixed(1)}</td>`;
450	    }
451	    tableHtml += '</tr>';
452	  }
453	  tableHtml += '</tbody></table>';
454	  compareTable.innerHTML = tableHtml;
455	  compareDiv.appendChild(compareTable);
456	  parent.appendChild(compareDiv);
457	
458	  // 绑定事件（延迟执行，等 DOM 插入完成）
459	  setTimeout(() => {
460	    // 购买按钮
461	    parent.querySelectorAll('.buy-btn').forEach(btn => {
462	      btn.addEventListener('click', (e) => {
463	        e.stopPropagation();
464	        const goodId = btn.dataset.good;
465	        const qty = parseInt(btn.dataset.qty) || 1;
