467	          buyGood(goodId, qty);
468	          renderCurrentTab(StateManager.getState(), parent.parentElement);
469	          renderSidebar(StateManager.getState());
470	          renderHeader(StateManager.getState());
471	          renderMessageLog(StateManager.getState());
472	        }
473	      });
474	    });
475	
476	    // 批发按钮
477	    parent.querySelectorAll('.wholesale-btn').forEach(btn => {
478	      btn.addEventListener('click', (e) => {
479	        e.stopPropagation();
480	        const goodId = btn.dataset.good;
481	        const qty = parseInt(btn.dataset.qty) || 10;
482	        if (typeof buyWholesale === 'function') {
483	          buyWholesale(goodId, qty);
484	          renderCurrentTab(StateManager.getState(), parent.parentElement);
485	          renderSidebar(StateManager.getState());
486	          renderHeader(StateManager.getState());
487	          renderMessageLog(StateManager.getState());
488	        }
489	      });
490	    });
491	
492	    // 卖出按钮（背包区）
493	    parent.querySelectorAll('.sell-one-btn').forEach(btn => {
494	      btn.addEventListener('click', (e) => {
495	        e.stopPropagation();
496	        const goodId = btn.dataset.good;
497	        if (typeof sellGood === 'function') {
498	          sellGood(goodId, 1);
499	          renderCurrentTab(StateManager.getState(), parent.parentElement);
500	          renderSidebar(StateManager.getState());
501	          renderHeader(StateManager.getState());
502	          renderMessageLog(StateManager.getState());
503	        }
504	      });
505	    });
506	
507	    parent.querySelectorAll('.sell-all-btn').forEach(btn => {
508	      btn.addEventListener('click', (e) => {
509	        e.stopPropagation();
510	        const goodId = btn.dataset.good;
511	        const item = StateManager.getState().inventory.items.find(i => i.id === goodId);
