588	  div.appendChild(equipDiv);
589	
590	  parent.appendChild(div);
591	}
592	
593	// ====== Skills Tab ======
594	function renderSkillsTab(state, parent) {
595	  const div = document.createElement('div');
596	  div.innerHTML = '<h3 style="color:var(--text-muted);margin-bottom:12px;">📚 技能</h3>';
597	
