57	
58	/* ====== Reset ====== */
59	*, *::before, *::after {
60	  box-sizing: border-box;
61	  margin: 0;
62	  padding: 0;
63	}
64	
65	html, body {
66	  height: 100%;
67	  overflow: hidden;
68	}
69	
70	body {
71	  font-family: var(--font-sans);
72	  font-size: 14px;
73	  line-height: 1.5;
74	  color: var(--text-primary);
75	  background: var(--bg-primary);
76	  -webkit-font-smoothing: antialiased;
77	}
78	
79	/* ====== Scrollbar ====== */
80	::-webkit-scrollbar {
81	  width: 6px;
82	  height: 6px;
83	}
84	::-webkit-scrollbar-track {
85	  background: transparent;
86	}
87	::-webkit-scrollbar-thumb {
88	  background: var(--border-light);
89	  border-radius: 3px;
90	}
91	::-webkit-scrollbar-thumb:hover {
92	  background: var(--text-muted);
93	}
