/* ================================================================
   城市浮生记 (City Life Story) — 全局样式
   设计参考: 互联网大厂模拟器 (bigtech-simulator.com)
   主题: 扁平化蓝色科技风
   ================================================================ */

/* ====== CSS 变量 / 主题 ====== */
:root {
  --bg-primary: #0a1628;
  --bg-secondary: #0f1d33;
  --bg-card: #152238;
  --bg-card-hover: #1a2f4a;
  --bg-sidebar: #0d1a2d;
  --bg-input: #0f1d33;

  --border: #1e3a5f;
  --border-light: #264b73;

  --text-primary: #e8edf5;
  --text-secondary: #8ba4c7;
  --text-muted: #5a7899;

  --accent: #00b4d8;
  --accent-glow: rgba(0, 180, 216, 0.15);
  --accent-hover: #0096b5;

  --success: #2ecc71;
  --success-bg: rgba(46, 204, 113, 0.1);
  --danger: #e74c3c;
  --danger-bg: rgba(231, 76, 60, 0.1);
  --warning: #f39c12;
  --warning-bg: rgba(243, 156, 18, 0.1);
  --info: #3498db;

  --hair-color: #7ec8e3;
  --mental-color: #c3b1e1;
  --kpi-color: #f9ca24;
  --risk-color: #e74c3c;
  --physique-color: #e67e22;
  --intelligence-color: #3498db;
  --agility-color: #2ecc71;
  --mental-attrs-color: #9b59b6;

  --font-mono: 'Consolas', 'Courier New', monospace;
  --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'PingFang SC',
    'Microsoft YaHei', sans-serif;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  --sidebar-width: 280px;
  --header-height: 48px;
  --transition: 0.2s ease;
}

/* ====== Reset ====== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  height: 100%;
  overflow: hidden;
}

body {
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  color: var(--text-primary);
  background: var(--bg-primary);
  -webkit-font-smoothing: antialiased;
}

/* ====== Scrollbar ====== */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--border-light);
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

/* ====== App Layout (CSS Grid) ====== */
#app {
  display: grid;
  grid-template-rows: var(--header-height) 1fr;
  grid-template-columns: var(--sidebar-width) 1fr;
  grid-template-areas:
    "header header"
    "sidebar main";
  height: 100vh;
  max-height: 100vh;
}

/* ====== Header ====== */
#header {
  grid-area: header;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  z-index: 100;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.header-logo {
  font-size: 18px;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 0.5px;
}

.header-logo span {
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 400;
  margin-left: 6px;
}

.header-stats {
  display: flex;
  align-items: center;
  gap: 20px;
  font-size: 13px;
}

.header-stat {
  display: flex;
  align-items: center;
  gap: 6px;
}

.header-stat .label {
  color: var(--text-muted);
  font-size: 11px;
}

.header-stat .value {
  color: var(--text-primary);
  font-weight: 600;
}

.header-stat .value.cash {
  color: var(--success);
}

.header-stat .value.age {
  color: var(--warning);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ====== Sidebar ====== */
#sidebar {
  grid-area: sidebar;
  background: var(--bg-sidebar);
  border-right: 1px solid var(--border);
  overflow-y: auto;
  overflow-x: hidden;
  padding: 16px 12px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.sidebar-section {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 12px;
  border: 1px solid transparent;
}

.sidebar-section h3 {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
  margin-bottom: 10px;
  font-weight: 600;
}

/* --- 属性条 --- */
.stat-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.stat-label {
  width: 50px;
  font-size: 12px;
  color: var(--text-secondary);
  text-align: right;
  flex-shrink: 0;
}

.stat-bar-wrap {
  flex: 1;
  height: 16px;
  background: rgba(255, 255, 255, 0.05);
  border-radius: var(--radius-sm);
  overflow: hidden;
  position: relative;
}

.stat-bar {
  height: 100%;
  border-radius: var(--radius-sm);
  transition: width var(--transition);
  position: relative;
}

.stat-bar.hair { background: linear-gradient(90deg, #4a90d9, var(--hair-color)); }
.stat-bar.dignity { background: linear-gradient(90deg, #7c5cbf, var(--mental-color)); }
.stat-bar.kpi { background: linear-gradient(90deg, #d4a017, var(--kpi-color)); }
.stat-bar.risk { background: linear-gradient(90deg, #c0392b, var(--risk-color)); }
.stat-bar.physique { background: linear-gradient(90deg, #c0651f, var(--physique-color)); }
.stat-bar.intelligence { background: linear-gradient(90deg, #2471a3, var(--intelligence-color)); }
.stat-bar.agility { background: linear-gradient(90deg, #1e8449, var(--agility-color)); }
.stat-bar.mental-bar { background: linear-gradient(90deg, #7d3c98, var(--mental-attrs-color)); }
.stat-bar.hunger { background: linear-gradient(90deg, #d4a017, #f9ca24); }
.stat-bar.fatigue { background: linear-gradient(90deg, #2c3e50, #5d6d7e); }
.stat-bar.hygiene { background: linear-gradient(90deg, #1a7a8a, #48c9b0); }
.stat-bar.happiness { background: linear-gradient(90deg, #c0392b, #e74c3c); }
.stat-bar.health { background: linear-gradient(90deg, #e74c3c, #2ecc71); }
.stat-bar.fame { background: linear-gradient(90deg, #8e44ad, #f39c12); }

.stat-value {
  width: 32px;
  font-size: 11px;
  color: var(--text-muted);
  text-align: right;
  flex-shrink: 0;
  font-family: var(--font-mono);
}

/* --- 地点 --- */
.location-display {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

.location-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--accent);
}

.location-desc {
  font-size: 11px;
  color: var(--text-muted);
}

/* ====== Main Content ====== */
#main {
  grid-area: main;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--bg-primary);
}

/* --- Tab Bar --- */
#tab-bar {
  display: flex;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  padding: 0 12px;
  flex-shrink: 0;
}

.tab-btn {
  padding: 10px 20px;
  font-size: 13px;
  color: var(--text-muted);
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  transition: all var(--transition);
  font-family: var(--font-sans);
}

.tab-btn:hover {
  color: var(--text-primary);
  background: rgba(255, 255, 255, 0.03);
}

.tab-btn.active {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

/* --- Content Area --- */
#content-area {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* --- Time Slot Indicator --- */
#time-slot-indicator {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  background: var(--bg-card);
  border-radius: var(--radius-md);
  font-size: 13px;
  flex-shrink: 0;
}

.time-slot-badge {
  padding: 2px 10px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  font-weight: 600;
}

.time-slot-badge.morning { background: rgba(243, 156, 18, 0.2); color: var(--warning); }
.time-slot-badge.afternoon { background: rgba(52, 152, 219, 0.2); color: var(--info); }
.time-slot-badge.evening { background: rgba(142, 68, 173, 0.2); color: #9b59b6; }

/* --- Action Cards Grid --- */
.action-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 10px;
}

.action-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 14px;
  cursor: pointer;
  transition: all var(--transition);
}

.action-card:hover {
  background: var(--bg-card-hover);
  border-color: var(--accent);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(0, 180, 216, 0.1);
}

.action-card.disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.action-card.disabled:hover {
  border-color: var(--border);
  transform: none;
  box-shadow: none;
}

.action-card .card-icon {
  font-size: 24px;
  margin-bottom: 6px;
}

.action-card .card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 4px;
}

.action-card .card-desc {
  font-size: 11px;
  color: var(--text-muted);
  margin-bottom: 8px;
  line-height: 1.4;
}

.action-card .card-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
}

.card-meta .pay-estimate {
  color: var(--success);
  font-weight: 600;
}

.card-meta .cost-estimate {
  color: var(--danger);
  font-weight: 600;
}

.card-meta .slot-tag {
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-size: 10px;
  background: rgba(0, 180, 216, 0.1);
  color: var(--accent);
}

.card-meta .req-fail {
  color: var(--danger);
  font-size: 10px;
}

/* --- Message Log --- */
#message-log {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 12px;
  max-height: 250px;
  overflow-y: auto;
  flex-shrink: 0;
}

#message-log h3 {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
  margin-bottom: 8px;
  font-weight: 600;
}

.log-entry {
  padding: 3px 0;
  font-size: 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.03);
  animation: fadeIn 0.3s ease;
}

.log-entry .log-day {
  color: var(--text-muted);
  font-size: 10px;
  margin-right: 8px;
  font-family: var(--font-mono);
}

.log-entry.info { color: var(--text-secondary); }
.log-entry.success { color: var(--success); }
.log-entry.danger { color: var(--danger); }
.log-entry.warning { color: var(--warning); }
.log-entry.event { color: var(--accent); font-weight: 600; }

/* --- Inventory Grid --- */
.inventory-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 8px;
}

.inventory-item {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 10px;
  font-size: 12px;
}

.inventory-item .item-name {
  font-weight: 600;
  color: var(--text-primary);
}

.inventory-item .item-qty {
  color: var(--text-muted);
  font-size: 10px;
}

.inventory-item .item-effects {
  color: var(--success);
  font-size: 10px;
}

/* ====== Buttons ====== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 16px;
  font-size: 13px;
  font-family: var(--font-sans);
  font-weight: 500;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition);
  background: var(--bg-card);
  color: var(--text-primary);
  white-space: nowrap;
}

.btn:hover {
  background: var(--bg-card-hover);
  border-color: var(--border-light);
}

.btn:active {
  transform: scale(0.97);
}

.btn-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.btn-primary:hover {
  background: var(--accent-hover);
}

.btn-success {
  background: var(--success);
  border-color: var(--success);
  color: #fff;
}

.btn-danger {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}

.btn-sm {
  padding: 4px 10px;
  font-size: 11px;
}

.btn-lg {
  padding: 12px 24px;
  font-size: 15px;
  border-radius: var(--radius-md);
}

/* ====== Modal ====== */
.modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0, 0, 0, 0.7);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  animation: fadeIn 0.2s ease;
}

.modal-box {
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 24px;
  min-width: 360px;
  max-width: 520px;
  max-height: 80vh;
  overflow-y: auto;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
  animation: slideUp 0.2s ease;
}

.modal-box h2 {
  font-size: 18px;
  margin-bottom: 12px;
  color: var(--text-primary);
}

.modal-box p {
  font-size: 13px;
  color: var(--text-secondary);
  margin-bottom: 16px;
  line-height: 1.6;
}

.modal-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

/* ====== Game Over / Victory Screen ====== */
.end-screen {
  text-align: center;
}

.end-screen .end-icon {
  font-size: 64px;
  margin-bottom: 16px;
}

.end-screen .end-title {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 8px;
}

.end-screen .end-subtitle {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

.end-screen.victory .end-title { color: var(--success); }
.end-screen.defeat .end-title { color: var(--danger); }

/* --- Stats Summary Table --- */
.stats-summary {
  width: 100%;
  border-collapse: collapse;
  margin: 16px 0;
}

.stats-summary td {
  padding: 6px 12px;
  font-size: 13px;
  border-bottom: 1px solid var(--border);
}

.stats-summary td:first-child {
  color: var(--text-muted);
}

.stats-summary td:last-child {
  text-align: right;
  font-weight: 600;
}

/* ====== News Banner ====== */
.news-banner {
  background: linear-gradient(135deg, var(--bg-card), rgba(0, 180, 216, 0.08));
  border: 1px solid var(--accent);
  border-left: 3px solid var(--accent);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  font-size: 12px;
  color: var(--accent);
  flex-shrink: 0;
}

.news-banner .news-icon {
  margin-right: 6px;
}

/* ====== Utility Classes ====== */
.text-success { color: var(--success); }
.text-danger { color: var(--danger); }
.text-warning { color: var(--warning); }
.text-accent { color: var(--accent); }
.text-muted { color: var(--text-muted); }
.text-sm { font-size: 11px; }
.text-lg { font-size: 16px; }
.font-mono { font-family: var(--font-mono); }

.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-2 { gap: 8px; }
.gap-4 { gap: 16px; }
.mt-2 { margin-top: 8px; }
.mt-4 { margin-top: 16px; }
.mb-2 { margin-bottom: 8px; }

/* ====== Animations ====== */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideUp {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

.pulse {
  animation: pulse 2s infinite;
}

/* ====== Welcome Screen ====== */
.welcome-screen {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100vh;
  gap: 24px;
  text-align: center;
}

.welcome-title {
  font-size: 36px;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 1px;
}

.welcome-subtitle {
  font-size: 14px;
  color: var(--text-muted);
  max-width: 400px;
  line-height: 1.6;
}

.welcome-buttons {
  display: flex;
  gap: 12px;
}

/* ====== Tab Content Panels ====== */
.tab-panel {
  display: none;
}

.tab-panel.active {
  display: block;
}

/* ====== Responsive: Mobile ====== */
@media (max-width: 768px) {
  #app {
    grid-template-columns: 1fr;
    grid-template-areas:
      "header"
      "main";
  }

  #sidebar {
    position: fixed;
    left: -100%;
    top: var(--header-height);
    bottom: 0;
    width: 280px;
    z-index: 200;
    transition: left 0.3s ease;
    box-shadow: 2px 0 8px rgba(0,0,0,0.3);
  }

  #sidebar.open {
    left: 0;
  }

  .action-cards {
    grid-template-columns: 1fr;
  }

  .header-stats {
    gap: 10px;
  }

  .header-stat .label {
    display: none;
  }

  #mobile-menu-btn {
    display: flex !important;
  }
}

#mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 20px;
  cursor: pointer;
  padding: 4px;
}

@media (min-width: 769px) {
  #mobile-menu-btn {
    display: none !important;
  }
}

#!/usr/bin/env python3
"""
构建脚本：将 src/ 下的所有 CSS/JS 内联到单个 index.html 中
输出到 dist/index.html（可独立部署的单文件）
"""

import re
import os

SRC_DIR = 'src'
DIST_DIR = 'dist'
OUTPUT_FILE = os.path.join(DIST_DIR, 'index.html')

def read_file(path):
    with open(path, 'r', encoding='utf-8') as f:
        return f.read()

def inline_css(html):
    """内联 <link rel="stylesheet"> """
    def replace_css(match):
        href = match.group(1)
        path = os.path.join(SRC_DIR, href)
        if os.path.exists(path):
            css = read_file(path)
            # 压缩CSS（简单版）
            css = re.sub(r'/\*.*?\*/', '', css, flags=re.DOTALL)
            css = re.sub(r'\s+', ' ', css)
            return f'<style>{css}</style>'
        return match.group(0)

    return re.sub(r'<link\s+rel="stylesheet"\s+href="([^"]+)"[^>]*>', replace_css, html)

def inline_js(html):
    """内联 <script src="..."> """
    def replace_js(match):
        attrs = match.group(0)
        src_match = re.search(r'src="([^"]+)"', attrs)
        if not src_match:
            return match.group(0)
        src = src_match.group(1)
        path = os.path.join(SRC_DIR, src)
        if os.path.exists(path):
            js = read_file(path)
            return f'<script>{js}</script>'
        return match.group(0)

    return re.sub(r'<script\s+src="([^"]+)"[^>]*></script>', replace_js, html)

def main():
    os.makedirs(DIST_DIR, exist_ok=True)

    html = read_file(os.path.join(SRC_DIR, 'index.html'))

    # 移除开发阶段的注释
    html = re.sub(r'<!-- =+\s*Scripts.*?-->', '', html, flags=re.DOTALL)

    # 内联 CSS
    html = inline_css(html)

    # 内联 JS（按顺序）
    html = inline_js(html)

    # 写入
    with open(OUTPUT_FILE, 'w', encoding='utf-8') as f:
        f.write(html)

    size_kb = os.path.getsize(OUTPUT_FILE) / 1024
    print(f'Build complete: {OUTPUT_FILE} ({size_kb:.1f} KB)')

