/** 获取地点服务标签 */
function getLocationServiceBadges(locKey) {
  const badges = [];
  const loc = getLocation(locKey);
  if (!loc) return badges;

  // 可租房
  if (locKey === 'slum') {
    badges.push({ icon: '🏠', label: '租房', bg: 'rgba(46,204,113,0.1)', color: 'var(--success)' });
  }
  // 可租仓库
  if (locKey === 'wholesaleMarket') {
    badges.push({ icon: '📦', label: '仓库', bg: 'rgba(243,156,18,0.1)', color: 'var(--warning)' });
  }
  // 医院
  if (locKey === 'hospital') {
    badges.push({ icon: '🏥', label: '看病', bg: 'rgba(231,76,60,0.1)', color: 'var(--danger)' });
  }
  // 银行
  if (locKey === 'bank') {
    badges.push({ icon: '🏦', label: '存取款', bg: 'rgba(52,152,219,0.1)', color: 'var(--info)' });
  }
  // 培训
  if (locKey === 'trainingCenter') {
    badges.push({ icon: '📚', label: '学习', bg: 'rgba(155,89,182,0.1)', color: '#9b59b6' });
  }
  // 公园
  if (locKey === 'park') {
    badges.push({ icon: '🌳', label: '放松', bg: 'rgba(46,204,113,0.1)', color: 'var(--success)' });
  }
  // 科技园
  if (locKey === 'techPark') {
    badges.push({ icon: '💼', label: '求职', bg: 'rgba(0,180,216,0.1)', color: 'var(--accent)' });
  }
  // 批发市场
  if (locKey === 'wholesaleMarket') {
    badges.push({ icon: '📦', label: '批发', bg: 'rgba(243,156,18,0.1)', color: 'var(--warning)' });
  }
  // 商业区
  if (locKey === 'commercialDist') {
    badges.push({ icon: '🛍️', label: '购物', bg: 'rgba(0,180,216,0.1)', color: 'var(--accent)' });
  }
  // 工作
  if (loc.jobs && loc.jobs.length > 0) {
    badges.push({ icon: '💼', label: `${loc.jobs.length}种工作`, bg: 'rgba(243,156,18,0.1)', color: 'var(--warning)' });
  }

  return badges;
}

