  // 可租仓库 & 批发
  if (locKey === 'wholesaleMarket') {
    badges.push({ icon: '📦', label: '仓库+批发', bg: 'rgba(243,156,18,0.1)', color: '#f39c12' });
  }
  // 医院
  if (locKey === 'hospital') {
    badges.push({ icon: '🏥', label: '看病', bg: 'rgba(231,76,60,0.1)', color: '#e74c3c' });
  }
  // 银行
  if (locKey === 'bank') {
    badges.push({ icon: '🏦', label: '存取款', bg: 'rgba(52,152,219,0.1)', color: '#3498db' });
  }
  // 培训
  if (locKey === 'trainingCenter') {
    badges.push({ icon: '📚', label: '学习考证', bg: 'rgba(155,89,182,0.1)', color: '#9b59b6' });
  }
  // 公园
  if (locKey === 'park') {
    badges.push({ icon: '🌳', label: '放松', bg: 'rgba(46,204,113,0.1)', color: '#2ecc71' });
  }
  // 科技园
  if (locKey === 'techPark') {
    badges.push({ icon: '💼', label: '应聘', bg: 'rgba(0,180,216,0.1)', color: '#00b4d8' });
  }
  // 商业区
  if (locKey === 'commercialDist') {
    badges.push({ icon: '🛍️', label: '购物+摆摊', bg: 'rgba(0,180,216,0.1)', color: '#00b4d8' });
